theorem prox_nonexpansive {f : ℝ → ℝ} (hconv : ConvexOn ℝ Set.univ f) {η x y p q : ℝ}
    (hη : 0 < η) (hp : IsProx f η x p) (hq : IsProx f η y q) :
    ‖p - q‖ ≤ ‖x - y‖

theorem sq_eq_zero_of_localMin {f : E → ℝ} {f' : E →L[ℝ] ℝ} {x : E}
    (hderiv : HasFDerivAt f f' x) (hne : f' ≠ 0)
    (hmin : IsLocalMin (fun y => f y ^ 2) x) : f x = 0

theorem round_close (F : FloatFormat) (r : RoundOp F) {x y η : ℝ}
    (h : |x - y| ≤ η) :
    |roundToFormat F r x - y| ≤ F.eps * |x| + F.tiny + η

theorem fp16_round_abs_bound (F : FloatFormat) (r : RoundOp F) {x : ℝ}
    (hx : |x| ≤ 65504) :
    |roundToFormat F r x| ≤ 65504 * (1 + F.eps) + F.tiny

theorem fp16_underflow_dominated (F : FloatFormat) (r : RoundOp F) {x : ℝ}
    (_hu : fp16Underflow x) (h : F.eps * |x| ≤ F.tiny) :
    |roundToFormat F r x - x| ≤ 2 * F.tiny

theorem loss_scaling_no_overflow (k : ℕ) {g : ℝ}
    (h : |g| ≤ fp16Max / (2 : ℝ) ^ k) :
    ¬ fp16Overflow ((2 : ℝ) ^ k * g)

theorem abs_resid_le_of_loss_le_sq {P X : Type} [TopologicalSpace X]
    (E : ResidualEmbedding P X) {ε : ℝ} (hε : 0 ≤ ε) (p : P) {x : X}
    (h : E.loss p x ≤ ε ^ 2) : |E.resid p x| ≤ ε

theorem loss_le_sq_of_resid_le {P X : Type} [TopologicalSpace X]
    (E : ResidualEmbedding P X) {ε : ℝ} (_hε : 0 ≤ ε) (p : P) {x : X}
    (h : |E.resid p x| ≤ ε) : E.loss p x ≤ ε ^ 2

theorem sq_localMin_dichotomy {f : E → ℝ} {f' : E →L[ℝ] ℝ} {x : E}
    (hderiv : HasFDerivAt f f' x) (hmin : IsLocalMin (fun y => f y ^ 2) x) :
    f x = 0 ∨ f' = 0
